protected function execute(InputInterface $input, OutputInterface $output): int
{
    try {
        $from = $this->parseInstant($input, 'from');
        $to = $this->parseInstant($input, 'to');
    } catch (ImportInputException $e) {
        $output->getErrorOutput()->writeln('usage error: '.$e->getMessage());

        return Command::FAILURE;
    }

    if ($from === null && $to !== null) {
        $output->getErrorOutput()->writeln('usage error: --from required when --to is given');

        return Command::FAILURE;
    }
    if ($from !== null && $to !== null && $from >= $to) {
        $output->getErrorOutput()->writeln('usage error: --from must be before --to');

        return Command::FAILURE;
    }

    $data = $this->report->build($from, $to);

    // CSV: разделитель «,», перевод строка \n, UTF-8
    $write = static function (string $line) use ($output): void {
        $output->write(str_replace(["\r\n", "\r"], "\n", $line)."\n");
    };

