    if ($from === null && $to !== null) {
        $output->getErrorOutput()->writeln('usage error: --from required when --to is given');

        return Command::FAILURE;
    }
    if ($from !== null && $to !== null && $from >= $to) {
        $output->getErrorOutput()->writeln('usage error: --from must be before --to');

        return Command::FAILURE;
    }

    $data = $this->report->build($from, $to);

    // CSV: разделитель «,», перевод строка \n, UTF-8
    $out = $output;
    $write = static function (string $line) use ($out): void {
        $out->write($line.PHP_EOL);
    };
    // Приводим переводы строк к \n независимо от платформы
    $write = static function (string $line) use ($out): void {
        $out->write(str_replace(["\r\n", "\r"], "\n", $line)."\n");
    };

