private function parseInstant(InputInterface $input, string $name, OutputInterface $output): ?\DateTimeImmutable
{
    $value = $input->getOption($name);
    if ($value === null || $value === false) {
        return null;
    }

    try {
        return UtcInstant::parse((string) $value);
    } catch (\InvalidArgumentException|\TypeError $e) {
        if ($e instanceof ImportInputException) {
            throw $e;
        }
        $output->getErrorOutput()->writeln(sprintf('usage error: --%s: %s', $name, $e->getMessage()));

        throw $e;
    }
}

